import{z as B,x as p,o as e,c as A,q as r,j as s,D as t,d as i,s as n,S as E,b as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"焦距、物距与横向放大","description":"","frontmatter":{"title":"焦距、物距与横向放大","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/focal-magnification.md","filePath":"litho/focal-magnification.md","lastUpdated":1791413859000}'),m={name:"litho/focal-magnification.md"};function M(d,a,h,f,c,D){const l=p("Mermaid");return e(),A("div",null,[a[2]||(a[2]=r('<h1 id="焦距、物距与横向放大" tabindex="-1">焦距、物距与横向放大 <a class="header-anchor" href="#焦距、物距与横向放大" aria-label="Permalink to &quot;焦距、物距与横向放大&quot;">​</a></h1><div class="epigraph"><p>横向放大率等于像距与物距之比的负号；投影缩小把掩模图形按固定比例搬到晶圆，掩模 CD 与晶圆 CD 差一个 $|M|$。</p><footer>—— 据 Hecht, Optics 对 lateral magnification 与共轭关系的整理</footer></div><p><a href="/litho/thin-lens-equation">上一课</a>给出 \\(\\frac{1}{s}+\\frac{1}{s&#39;}=\\frac{1}{f}\\)。本课不重推该式。缺口是：像比物大还是小？\\(M\\) 与掩模尺寸、晶圆 CD、物像双方孔径如何一起约束？后课光瞳与视场都默认横向放大是已知数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>成像方程只含轴向距离，不直接说「掩模上 1 μm 在晶圆上是多少」。工程投影倍率常写 4:1 或 5:1，即 \\(|M|=1/4\\) 或 \\(1/5\\)。若不会 \\(M=-s&#39;/s\\)，无法把掩模图形与晶圆图形对应，也无法理解掩模缺陷缩小后为什么「看起来更小」（可印性仍是后课）。缺口是横向几何，不是再选一个焦距。</p><p><span class="marginnote">数字实例：\\(|M| = 1/4\\) 时，掩模上画 4 µm 的线，晶圆上得到 1 µm；掩模上落了 100 nm 的颗粒，折算到晶圆面只有 25 nm。这解释了两件事：为什么 4:1 缩小让掩模好做、好检查（图案放大了四倍），也为什么掩模厂的缺陷控制反而更苛刻——颗粒看起来小，但掩模本来就该「大四倍」。</span></p><h3 id="倒像的负号不是缺陷" tabindex="-1">倒像的负号不是缺陷 <a class="header-anchor" href="#倒像的负号不是缺陷" aria-label="Permalink to &quot;倒像的负号不是缺陷&quot;">​</a></h3><p>\\(M\\lt 0\\) 表示倒像：物方朝上的箭头，像方朝下。光刻投影通常倒像，套刻与掩模版图在数据上已经折过取向。把 \\(|M|\\) 当成正数倍率没问题，但丢负号会在画光路时把上下搞反。本课保留负号，口头说「缩小四倍」时指绝对值。</p><p><span class="marginnote">常见误区：初学者容易把工程口径的「4:1」读成放大四倍。投影光刻的惯例是 4:1 表示四倍缩小，\\(|M| = 1/4\\)——掩模大、晶圆小。另外负号只管「倒不倒」，绝对值才管「缩多少」，两个信息别混在一个数里说。</span></p><p><span class="marginnote">\\(M=h&#39;/h=-s&#39;/s\\)。缩小：\\(|M|\\lt 1\\)，且由成像方程知 \\(|s&#39;|\\lt |s|\\)（会聚透镜、实像）。纵向放大约 \\(M^2\\)，焦深缩放后课才用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>近轴横向放大率如上。与成像方程联立：给定 \\(f\\) 与 \\(s\\)，先解 \\(s&#39;\\) 再得 \\(M\\)。固定 \\(f\\) 时，\\(s\\to f^+\\) 则 \\(|M|\\to\\infty\\)（显微镜工况）；\\(s\\gg f\\) 则 \\(|M|\\to 0\\)。投影光刻选中等缩小：掩模比晶圆大，便于制造与检验，又把物镜口径控制在可做的范围。</p><p>选 4:1 而不是 10:1，是掩模尺寸、物镜口径与视场的折中：缩得太狠，掩模上同一视场变得过大，或物方 NA 小到照明与对准都别扭。本课不优化这个数，只说明 \\(|M|\\) 一旦选定，掩模与晶圆上的所有横向尺寸都按它换算，包括下一课视场光阑在两边的开口。</p><p>物方 NA 与像方 NA 通过 \\(|M|\\) 关联（近轴、同一介质）：\\(\\mathrm{NA}_{\\mathrm{obj}}\\approx |M|\\,\\mathrm{NA}_{\\mathrm{img}}\\)。像方 NA 进入后课分辨率语言；物方 NA 决定掩模侧照明锥角。本课只把关系写下，不把分辨公式提前展开。</p>',14)),(e(),s(E,null,{default:t(()=>[n(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20GAUSS%5B%221%2Fs%20%2B%201%2Fs'%20%3D%201%2Ff%22%5D%20--%3E%20M%5B%22M%20%3D%20-s'%2Fs%22%5D%0A%20%20M%20--%3E%20MASK%5B%22%E6%8E%A9%E6%A8%A1%E5%B0%BA%E5%AF%B8%22%5D%0A%20%20M%20--%3E%20WAFER%5B%22%E6%99%B6%E5%9C%86%E5%9B%BE%E5%BD%A2%E5%B0%BA%E5%AF%B8%22%5D%0A%20%20MASK%20--%3E%20RATIO%5B%22%E7%BC%A9%E5%B0%8F%E6%8A%95%E5%BD%B1%E5%80%8D%E7%8E%87%22%5D%0A%20%20WAFER%20--%3E%20RATIO%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[i("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"缩小使掩模上的误差与缺陷在晶圆上按 \\(|M|\\) 缩小——这是选 4:1 而不是 1:1 的经典理由之一。同时物镜要在像方张开更大的角，才能维持拉格朗日不变量（下一课 étendue 的近亲）。纵向放大 \\(M^2\\) 意味着物方离焦到像方会被「压扁」或「拉长」；\\(|M|=1/4\\) 时像方焦深对物方离焦不那么敏感，掩模轴向公差相对宽松。",-1)),(e(),s(E,null,{default:t(()=>[n(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20MC%5B%22%E6%8E%A9%E6%A8%A1%20CD%22%5D%20--%3E%7C%22%E4%B9%98%20M%20%E7%BB%9D%E5%AF%B9%E5%80%BC%22%7C%20WC%5B%22%E6%99%B6%E5%9C%86%20CD%22%5D%0A%20%20MD%5B%22%E6%8E%A9%E6%A8%A1%E7%BC%BA%E9%99%B7%E5%B0%BA%E5%AF%B8%22%5D%20--%3E%7C%22%E4%B9%98%20M%20%E7%BB%9D%E5%AF%B9%E5%80%BC%22%7C%20WD%5B%22%E6%99%B6%E5%9C%86%E7%BC%BA%E9%99%B7%E5%B0%BA%E5%AF%B8%22%5D%0A%20%20MZ%5B%22%E6%8E%A9%E6%A8%A1%E8%BD%B4%E5%90%91%E5%81%8F%E7%A7%BB%22%5D%20--%3E%7C%22%E4%B9%98%20M%20%E7%9A%84%E5%B9%B3%E6%96%B9%22%7C%20WI%5B%22%E5%83%8F%E6%96%B9%E7%AD%89%E6%95%88%E7%A6%BB%E7%84%A6%22%5D%0A%20%20NI%5B%22%E5%83%8F%E6%96%B9%20NA%22%5D%20--%3E%7C%22%E4%B9%98%20M%20%E7%BB%9D%E5%AF%B9%E5%80%BC%22%7C%20NO%5B%22%E7%89%A9%E6%96%B9%20NA%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p>这张图回答的问题是：掩模侧与晶圆侧的哪些量按 \\(|M|\\) 换算、哪些按 \\(M^2\\) 换算。横向尺寸与孔径都走一次 \\(|M|\\)，唯独轴向位置走平方——记住这张换算表，套刻与缺陷预算里的几何项就不会放错倍数。</p><p><span class="marginnote">数字实例：\\(|M| = 1/4\\) 时纵向放大约 \\(1/16\\)——掩模沿轴向偏 1 µm，在像方只造成约 1/16 µm 的等效离焦。所以掩模的平整度、厚度公差可以比晶圆的焦深松一个量级，这是缩小投影「白送」的第二条几何红利。</span></p><p>畸变会让 \\(M\\) 随视场位置变，套刻把畸变当误差预算，而不是把本课的常数 \\(M\\) 作废。<a href="/litho/geometric-aberration-tour">几何像差一览</a> 再分类。各向异性倍率（某些 EUV 投影 \\(M_x\\neq M_y\\)）是机台特例，本课各向同性为零阶。</p><p>缩小还改掩模与晶圆上的缺陷「看起来」差一个 \\(|M|\\)：掩模上同样物理尺寸的缺陷，到晶圆按倍率缩小。可印性仍取决于缺陷的空间频率是否进得了光瞳，那是后课；本课只提供几何缩放。纵向放大 \\(M^2\\) 则让物方离焦映射到像方时被压缩，掩模轴向公差相对晶圆焦深更宽，这是选缩小投影的另一条几何理由。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课 paraxial、薄透镜、单色、无光阑。谁限制光束截面、视场有多大，是下一课 <a href="/litho/stop-pupil-fov">光阑、光瞳与视场</a>。也不讨论扫描狭缝如何把瞬时视场拼成全场。</p><p>纵向放大与折射率有关：物方、像方介质不同时，\\(M_{\\mathrm{long}}\\) 还要乘 \\(n\\) 的比。浸没只改像方时，焦深换算要小心。后课默认：投影倍率 \\(|M|\\) 已知；晶圆尺寸 = \\(|M|\\) 乘掩模尺寸；像方与物方孔径角差一个 \\(|M|\\)。谈到「4 倍缩小」，就是本课的 \\(|M|\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>横向放大 \\(M=-s&#39;/s\\)；投影缩小 \\(|M|\\lt 1\\)，通常倒像。</li><li>掩模 CD 与晶圆 CD 差 \\(|M|\\) 倍；物像双方 NA 也差 \\(|M|\\)。</li><li>纵向放大约 \\(M^2\\)，影响焦深与掩模轴向公差。</li><li>畸变使 \\(M\\) 随视场变，属像差，不改零阶定义。</li><li>出处：Hecht, <em>Optics</em>；Born &amp; Wolf, <em>Principles of Optics</em>。</li></ul>',9))])}const u=B(m,[["render",M]]);export{_ as __pageData,u as default};
